import pytest
from sanic import Sanic
from sanic.response import HTTPResponse
from sanic.request import Request
from sanic.exceptions import NotFound

app = Sanic()
app.add_exception_handler(NotFound, lambda *args: HTTPResponse())

@app.route('/hello', methods=['GET'])
async def hello(request):
    return HTTPResponse("Hello, world!")

@app.middleware('request')
async def add_url_parameter(request):
    request.ctx.url_parameter = "foo"

@app.middleware('response')
async def modify_response(request, response):
    response.headers['X-Modified'] = True

def test_sanic_named_middleware():
    request = Request(
        method="GET",
        path="/hello",
        url="http://testserver/hello",
        headers={
            'Host': 'testserver'
        },
        version=1.1
    )
    app.router.add_route(hello, '/hello')
    app.register_named_middleware(add_url_parameter, ['hello'],'request')
    app.register_named_middleware(modify_response, ['hello'],'response')

    response = app.test_client.get('/hello')

    assert response.status == 200
    assert response.headers['X-Modified']
    assert response.ctx.url_parameter == "foo"

